/* 布局·侧边导航 —— 左轨右文，文档式 */
@media (min-width: 901px) {
  body.l-side-nav nav {
    left: 0; top: 38px; bottom: 0; right: auto; width: 210px;
    border-bottom: none; border-right: 1.5px solid var(--border);
  }
  body.l-side-nav .nav-inner {
    flex-direction: column; align-items: flex-start;
    padding: 30px 24px; height: 100%; gap: 26px; max-width: none;
  }
  body.l-side-nav .nav-links {
    flex-direction: column; margin-left: 0; margin-top: 24px; gap: 18px;
  }
  body.l-side-nav .nav-links a { font-size: 15px; }
  body.l-side-nav .gallery-link { margin-left: 0; margin-top: auto; }
  body.l-side-nav .hero,
  body.l-side-nav section,
  body.l-side-nav footer { margin-left: 210px; max-width: 860px; }
  body.l-side-nav .hero { min-height: 92vh; }
  body.l-side-nav footer { margin-right: auto; }
}
